{"packet_id": "D043-01", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA RSO and JCO no-fault eviction: relocation assistance and declaration filing", "requirement": "For every no-fault eviction of an RSO or JCO unit the landlord must pay relocation assistance and file a Declaration of Intent to Evict with LAHD before evicting; failure to file makes the eviction a violation.", "key_value": null, "coverage_conditions": "All not-at-fault evictions from rental units covered by the Rent Stabilization Ordinance or the Just Cause Ordinance.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": "Evicting a resident manager to replace him or her; evictions required by hazardous conditions from a natural disaster not caused by landlord negligence; landlord may offset accumulated rent except for a governmental order to vacate or unpermitted dwelling.", "penalty": "Filing failure makes the eviction a violation of the RSO or JCO; tenant may raise non-payment as an affirmative defense and file a complaint with LAHD.", "effective_date": null, "citation": "LAMC § 151.09, no-fault eviction relocation assistance and declaration of intent to evict", "quoted_span": "All tenant not- at-fault evictions require payment of relocation assistance and the filing of a Declaration of Intent to Evict form with the Los Angeles Housing Department (LAHD) before evicting tenants from units covered by the Rent Stabilization Ordinance (RSO) or the Just Cause Ordinance (JCO). Failure to file the Landlord Declaration with the LAHD makes the eviction a violation of the RSO or JCO.", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-01", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA RSO/JCO relocation assistance amounts 2026-27", "requirement": "Relocation assistance for a no-fault displacement is paid per unit, not per tenant, at the Chart A amounts, which rise every July 1st.", "key_value": "$10,550 to $27,400 per unit", "coverage_conditions": "Tenants displaced for a no-fault reason from RSO or JCO units; amount depends on eligible or qualified status, length of tenancy and low income at or below 80% AMI.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "Amount depends on tenant status, tenancy length and income"}, "exemptions": "Amounts do not apply where a Protected Unit is demolished for new construction and the tenant is lower income at or below 80% AMI.", "penalty": null, "effective_date": "2026-07-01", "citation": "LAMC § 165.06, relocation assistance amounts, Chart A, 2026-2027", "quoted_span": "Household $11,000 $14,400 $10,550 One month’s rent Qualified Household $23,150 $27,400 $21,250 Increases every July 1st.", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-01", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA JCO relocation for single-family dwelling owned by a natural person", "requirement": "Where a JCO single-family dwelling is owned by a natural person with no more than four dwelling units and one separate single-family home, relocation assistance is one month's rent in effect when the termination notice was served.", "key_value": "1 month's rent", "coverage_conditions": "Single-family dwellings subject to the JCO owned by a natural person, including through a trust or controlled legal entity, who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": 4, "owner_dependent": true, "other": "Single-family dwelling owned by a natural person"}, "exemptions": "Los Angeles Municipal Code Section 151.30(E) shall not apply.", "penalty": null, "effective_date": null, "citation": "LAMC § 165.06, single-family dwelling owned by natural person: one month's rent", "quoted_span": "a single-family dwelling subject to the JCO and the owner is a natural person, including natural persons who hold properties in a trust or registered legal entity controlled by   that natural person, who owns no more than four dwelling units and a single-family home on a separate lot in the City of Los Angeles: one month’s rent that was in effect when   the landlord served the written notice to terminate the tenancy", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-01", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA Resident Protections Ordinance relocation for demolition for new construction", "requirement": "An owner who demolishes a Protected Unit for new construction within five years of filing with LAHD must comply with RPO relocation requirements for the displaced lower income households.", "key_value": null, "coverage_conditions": "Owners demolishing a Protected Unit for the purpose of new construction within 5 years of filing; enhanced relocation only for lower income households at or below 80% AMI.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "Protected Unit demolished for new construction"}, "exemptions": null, "penalty": "Failure to comply may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.", "effective_date": "2025-02-11", "citation": "Los Angeles Resident Protections Ordinance #188481, relocation for demolition and new construction", "quoted_span": "Owners who demolish a Protected Unit for the purpose of new construction within 5 years after the filing of the Notice of Intent to Withdraw or Declaration of Intent to Evict with LAHD are required to comply with relocation requirements under the RPO. Failure to comply with the RPO may result in financial penalties starting at $250,000 per displaced unit and withholding of LAHD permit clearances.", "interaction": "Landlord must pay the higher of state Housing Crisis Act and city RSO or JCO relocation amounts.", "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-01", "doc_id": "D043", "jurisdiction": "CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "California Housing Crisis Act relocation for lower income tenants displaced by new construction", "requirement": "Lower income households displaced by demolition of their unit where the owner will build new construction must receive relocation payment consistent with the benefits public entities must pay.", "key_value": null, "coverage_conditions": "Lower income households at or below 80% AMI displaced by demolition of their unit where the owner will replace the units with new construction.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": "Lower income household displaced by demolition for new construction"}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "Cal. Gov. Code § 66300.6", "quoted_span": "● Demolition for New Construction The City’s Resident Protections Ordinance (RPO) and the State’s Housing Crisis Act (HCA) require that ONLY lower income households (80%  AMI or lower) being displaced for demolition of their units where the owner will replace the units with new construction receive relocation payment consistent to the relocation benefits required to be paid by public entities under Chapter 16 (commencing with Section 7260) of Division 7 of Title 1 (Government Code 66300.6(b)(4)(A)).", "interaction": "All tenants displaced for new construction receive at least the RSO or JCO amounts, increased only if the HCA or RPO requires it.", "confidence": 0.7, "conflict_flag": false, "conflict_note": null}
{"packet_id": "D043-01", "doc_id": "D043", "jurisdiction": "Los Angeles, CA", "category": "just_cause_eviction", "lifecycle": "enacted", "title": "LA relocation assistance payment timing", "requirement": "Relocation assistance must be made available to the tenant within 15 days of service of the written notice of eviction, unless the landlord elects to pay through an escrow account.", "key_value": "15 days", "coverage_conditions": "Relocation assistance owed to tenants displaced by a no-fault eviction from RSO or JCO units.", "applicability": {"built_on_or_before": null, "built_after": null, "date_basis": null, "min_units": null, "max_units": null, "owner_dependent": false, "other": null}, "exemptions": null, "penalty": null, "effective_date": null, "citation": "LAMC § 165.06, relocation assistance payment timing", "quoted_span": "The Ordinance requires timely relocation assistance payments as follows: 1. Payment shall be made available within fifteen (15) days of service of the written notice of eviction; however,", "interaction": null, "confidence": 0.75, "conflict_flag": false, "conflict_note": null}
